const cn=(names:string)=>componentClasses(styles,names);

const states: { value: CallChipStatus; label: string }[] = [{ value: 'idle', label: '等待' }, { value: 'running', label: '运行' }, { value: 'done', label: '成功' }, { value: 'error', label: '失败' }];
