    <p className={cn("aw-micro-status")} role="status" aria-live="polite">已选：{value ? `${value} 分 · ${labels[value - 1]}` : '未评分'}{preview ? `；正在预览 ${preview} 分` : ''}</p>
  </div></DemoPanel>;
}

