const ownedStyles={...ownedStyles0,...ownedStyles1,...ownedStyles2};
const cn=(names:string)=>componentClasses(ownedStyles,names);
export default function BusinessStepperDemo() {
  const [step, setStep] = useState(0);
  const [name, setName] = useState('');
  const steps = ['填写资料', '确认范围', '完成'];
  const reduced = useBusinessReducedMotion();
  return <BusinessDemo title="Stepper" description="阶段标记、进度与内容同步过渡，返回上一步时保留输入。">
    <ol data-ui="aw-business-flow-steps" className={cn("aw-business-flow-steps")}>{steps.map((label, index) => <li key={label} aria-current={index === step ? 'step' : undefined} data-complete={index < step}><motion.span data-ui="aw-business-step-number" className={cn("aw-business-step-number")} animate={{ scale: index === step && !reduced ? 1.08 : 1 }} transition={reduced ? { duration: 0 } : controlSpring}>{index < step ? <Check size={16} aria-hidden="true" /> : index + 1}</motion.span><span>{label}</span></li>)}</ol>
    <div data-ui="aw-business-flow-progress" className={cn("aw-business-flow-progress")} aria-hidden="true"><motion.div initial={false} animate={{ width: `${step / (steps.length - 1) * 100}%` }} transition={reduced ? { duration: 0 } : controlSpring} /></div>
    <AnimatedSwap value={step}><section data-ui="aw-business-item" className={cn("aw-business-item")}>{step === 0 ? <Field label="任务名称"><input data-ui="aw-business-input" className={cn("aw-business-input")} value={name} onChange={event => setName(event.target.value)} /></Field> : step === 1 ? <p>将为“{name}”保存当前页面的本地示例状态。</p> : <p role="status">“{name}”的本地流程已完成。</p>}</section></AnimatedSwap>
    <div data-ui="aw-business-row" className={cn("aw-business-row")}><Button variant="secondary" disabled={step === 0} onClick={() => setStep(value => value - 1)}>上一步</Button><Button disabled={step === 2 || !name.trim()} onClick={() => setStep(value => value + 1)}>下一步</Button><Button variant="secondary" onClick={() => { setStep(0); setName(''); }}>重置</Button></div>
  </BusinessDemo>;
}

business-tabs.source:
import { useId, useState } from 'react';
import { LayoutGroup } from 'motion/react';
import { Activity, LayoutDashboard, Settings } from 'lucide-react';
import { BusinessDemo } from '../../components/BusinessDemo';
import { AnimatedSwap } from '../../components/AnimatedSwap';
import { SelectionIndicator } from '../../components/SelectionIndicator';
import { useBusinessReducedMotion } from '../../motion-preference';
import styles from './business-tabs.module.css';

export default function BusinessTabsDemo() {
  const [active, setActive] = useState(0);
  const tabs = ['概览', '活动', '设置'];
  const icons = [LayoutDashboard, Activity, Settings];
  const prefix = useId();
  const reduced = useBusinessReducedMotion();

  return <BusinessDemo title="Tabs" description="选中背景弹性滑动，面板轻盈切换；方向键同步标签和焦点。">
    <LayoutGroup id={prefix}>
      <div data-ui="aw-business-animated-tabs" data-motion={reduced ? 'reduce' : 'allow'} role="tablist" aria-label="工作空间内容" className={styles.tabList}>
        {tabs.map((label, index) => {
          const Icon = icons[index];
          return <button className={styles.tab} type="button" key={label} id={`${prefix}-tab-${index}`} role="tab" aria-selected={active === index} aria-controls={`${prefix}-panel-${index}`} tabIndex={active === index ? 0 : -1} onClick={() => setActive(index)} onKeyDown={event => {
            if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
            event.preventDefault();
            const next = event.key === 'Home' ? 0 : event.key === 'End' ? tabs.length - 1 : (index + (event.key === 'ArrowLeft' ? -1 : 1) + tabs.length) % tabs.length;
            setActive(next);
            document.getElementById(`${prefix}-tab-${next}`)?.focus();
          }}>
            {active === index ? <SelectionIndicator identity={`${prefix}-selected`} /> : null}
            <Icon className={styles.tabIcon} size={16} aria-hidden="true" /><span className={styles.tabLabel}>{label}</span>
          </button>;
        })}
      </div>
    </LayoutGroup>
    {tabs.map((label, index) => <section id={`${prefix}-panel-${index}`} role="tabpanel" aria-labelledby={`${prefix}-tab-${index}`} tabIndex={0} hidden={active !== index} key={label}>
      {active === index ? <AnimatedSwap value={active}><div data-ui="aw-business-item" className={styles.panel}><h3 className={styles.panelTitle}>{label}</h3><p className={styles.panelCopy}>{index === 0 ? '当前空间有6项本地任务。' : index === 1 ? '这里显示当前示例的活动摘要。' : '工作空间设置可按业务权限接入。'}</p></div></AnimatedSwap> : null}
    </section>)}
  </BusinessDemo>;
}

