business-message.source:
import { useId, useRef, useState, type ChangeEvent, type FormEvent } from 'react';
import { AnimatePresence, motion, useIsPresent } from 'motion/react';
import { CheckCircle2, CircleAlert } from 'lucide-react';
import { BusinessDemo } from '../../components/BusinessDemo';
import { Button } from '../../components/Button';
import { Field } from '../../components/Field';
import inputStyles from '../../components/Input.module.css';
import { useBusinessReducedMotion } from '../../motion-preference';
import styles from './business-message.module.css';

type Message = { text: string; error: boolean };

function MessageNotice({ message, id, reduced, onDismiss }: {
  message: Message;
  id: string;
  reduced: boolean;
  onDismiss: () => void;
}) {
  const present = useIsPresent();
  const Icon = message.error ? CircleAlert : CheckCircle2;

  return (
    <motion.div
      className={styles.message}
      data-tone={message.error ? 'error' : 'success'}
      role={message.error ? 'alert' : 'status'}
      inert={!present}
      aria-hidden={!present || undefined}
      initial={reduced ? false : { opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: reduced ? 0 : -6 }}
      transition={{ duration: reduced ? 0 : 0.18 }}
    >
      <Icon className={styles.icon} size={18} aria-hidden="true" />
      <span id={id} className={styles.messageText}>{message.text}</span>
      <Button variant="ghost" data-size="sm" aria-label="关闭消息" onClick={onDismiss}>关闭</Button>
    </motion.div>
  );
}

export default function BusinessMessageDemo() {
  const [value, setValue] = useState('');
  const [message, setMessage] = useState<Message | null>(null);
  const reduced = useBusinessReducedMotion();
  const inputRef = useRef<HTMLInputElement>(null);
  const messageId = useId();

  function changeValue(event: ChangeEvent<HTMLInputElement>) {
    setValue(event.target.value);
  }

  function validate(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setMessage(value.trim()
      ? { text: '名称已在当前页面校验通过。', error: false }
      : { text: '请先填写名称。', error: true });
  }

  function dismissMessage() {
    setMessage(null);
    inputRef.current?.focus();
  }

  return (
    <BusinessDemo title="Message" description="根据本地表单校验呈现成功或错误信息，关闭后可重新提交。">
      <form className={styles.form} onSubmit={validate}>
        <Field label="名称">
          <input
            ref={inputRef}
            data-ui="aw-business-input"
            className={inputStyles['aw-business-input']}
            value={value}
            aria-invalid={message?.error || undefined}
            aria-describedby={message ? messageId : undefined}
            onChange={changeValue}
          />
        </Field>
        <Button className={styles.submit} type="submit">校验</Button>
      </form>
      <AnimatePresence mode="wait">
        {message ? (
          <MessageNotice
            key={message.error ? 'error' : 'success'}
            message={message}
            id={messageId}
            reduced={reduced}
            onDismiss={dismissMessage}
          />
        ) : null}
      </AnimatePresence>
    </BusinessDemo>
  );
}

business-toast.source:
import { useCallback, useEffect, useRef, useState, type MouseEvent, type Ref } from 'react';
import { AnimatePresence, motion, useIsPresent } from 'motion/react';
import { CheckCircle2, Info } from 'lucide-react';
import { BusinessDemo } from '../../components/BusinessDemo';
import { Button } from '../../components/Button';
import { useBusinessReducedMotion } from '../../motion-preference';
import styles from './business-toast.module.css';

function ToastNotice({ notice, reduced, innerRef, onDismiss }: {
  notice: string;
  reduced: boolean;
  innerRef: Ref<HTMLDivElement>;
  onDismiss: () => void;
}) {
  const present = useIsPresent();
  const success = notice === '本地草稿已保存。';
  const Icon = success ? CheckCircle2 : Info;

  return (
    <motion.div
      ref={innerRef}
      className={styles.toast}
      data-tone={success ? 'success' : 'info'}
      role="status"
      aria-atomic="true"
      inert={!present}
      aria-hidden={!present || undefined}
      initial={reduced ? false : { opacity: 0, y: 20, scale: 0.96 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: reduced ? 0 : 12, scale: reduced ? 1 : 0.97 }}
      transition={{ duration: reduced ? 0 : 0.2, ease: [0.22, 1, 0.36, 1] }}
    >
      <span className={styles.icon} aria-hidden="true"><Icon size={20} /></span>
      <span className={styles.text}>{notice}</span>
      <Button variant="ghost" data-size="sm" aria-label="关闭提示" onClick={onDismiss}>关闭</Button>
    </motion.div>
  );
}

export default function BusinessToastDemo() {
  const [notice, setNotice] = useState<string | null>(null);
  const [sequence, setSequence] = useState(0);
  const reduced = useBusinessReducedMotion();
  const noticeRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement | null>(null);

  const dismissNotice = useCallback(() => {
    // Return keyboard focus before the departing notification becomes inert.
    if (noticeRef.current?.contains(document.activeElement)) triggerRef.current?.focus();
    setNotice(null);
  }, []);

  useEffect(() => {
    if (!notice) return;
    const timer = window.setTimeout(dismissNotice, 4000);
    return () => window.clearTimeout(timer);
  }, [notice, sequence, dismissNotice]);

  function showSuccess(event: MouseEvent<HTMLButtonElement>) {
    triggerRef.current = event.currentTarget;
    setSequence(value => value + 1);
    setNotice('本地草稿已保存。');
  }

  function showInfo(event: MouseEvent<HTMLButtonElement>) {
    triggerRef.current = event.currentTarget;
    setSequence(value => value + 1);
    setNotice('可以继续完善草稿内容。');
  }

  return (
    <BusinessDemo title="Toast" description="短消息在本地出现，可手动关闭，4秒后自动移除；卸载时清理计时器。">
      <div className={styles.controls}>
        <Button onClick={showSuccess}>显示成功提示</Button>
        <Button variant="secondary" onClick={showInfo}>显示普通提示</Button>
      </div>
      <div className={styles.viewport}>
        <AnimatePresence mode="wait">
          {notice ? (
            <ToastNotice
              key={sequence}
              notice={notice}
              reduced={reduced}
              innerRef={noticeRef}
              onDismiss={dismissNotice}
            />
          ) : null}
        </AnimatePresence>
      </div>
    </BusinessDemo>
  );
}

