import { useState, type ChangeEvent } from 'react';
import { motion } from 'motion/react';
import { RangeSlider } from '../../components/RangeSlider';
import { BusinessDemo } from '../../components/BusinessDemo';
import { Field } from '../../components/Field';
import { useBusinessReducedMotion } from '../../motion-preference';
import styles from './business-metergroup.module.css';

export default function BusinessMeterGroupDemo() {
  const [knowledge, setKnowledge] = useState(45);
  const reduced = useBusinessReducedMotion();
  const groups = [
    { label: '知识', value: knowledge, color: 'var(--aw-palette-primary)' },
    { label: '文档', value: Math.round((100 - knowledge) * 0.6), color: 'var(--aw-palette-scene-sand)' },
    { label: '服务', value: 100 - knowledge - Math.round((100 - knowledge) * 0.6), color: 'var(--aw-palette-effect-terra)' },
  ];
  const transition = { duration: reduced ? 0 : 0.4, ease: [0.22, 1, 0.36, 1] as const };

  function changeKnowledge(event: ChangeEvent<HTMLInputElement>) {
    setKnowledge(Number(event.target.value));
  }

  return (
    <BusinessDemo title="MeterGroup" description="分组展示资料容量分配，调整知识占比后其他类别自动保持总和100%。">
      <Field control label={`知识占比：${knowledge}%`}>
        <RangeSlider min="0" max="100" value={knowledge} onChange={changeKnowledge} />
      </Field>
      <div className={styles.allocation} aria-hidden="true">
        {groups.map(group => (
          <motion.div
            key={group.label}
            className={styles.segment}
            style={{ background: group.color }}
            initial={false}
            animate={{ width: `${group.value}%` }}
            transition={transition}
          />
        ))}
      </div>
      <ul className={styles.legend} aria-label="资料容量分配">
        {groups.map(group => (
          <li key={group.label} className={styles.item}>
            <div className={styles.heading}>
              <span className={styles.dot} style={{ background: group.color }} aria-hidden="true" />
              <span>{group.label}</span>
              <span className={styles.value} aria-hidden="true">{group.value}%</span>
            </div>
            <meter className={styles.meterSemantics} min="0" max="100" value={group.value} aria-label={group.label + '占比'}>{group.value}%</meter>
            <div className={styles.track} aria-hidden="true">
              <motion.span
                className={styles.fill}
                style={{ background: group.color }}
                initial={false}
                animate={{ scaleX: group.value / 100 }}
                transition={transition}
              />
            </div>
          </li>
        ))}
      </ul>
    </BusinessDemo>
  );
}

business-progressbar.source:
import { useId, useState } from 'react';
import { motion } from 'motion/react';
import { CheckCircle2 } from 'lucide-react';
import { BusinessDemo } from '../../components/BusinessDemo';
import { Button } from '../../components/Button';
import { useBusinessReducedMotion } from '../../motion-preference';
import styles from './business-progressbar.module.css';

export default function BusinessProgressBarDemo() {
  const [progress, setProgress] = useState(20);
  const reduced = useBusinessReducedMotion();
  const progressId = useId();
  const complete = progress === 100;

  function advance() {
    setProgress(value => Math.min(100, value + 20));
  }

  function reset() {
    setProgress(0);
  }

  return (
    <BusinessDemo title="ProgressBar" description="本地步骤完成度由按钮驱动，终值限制在100%，可重置。">
      <div className={styles.card}>
        <div className={styles.heading}>
          <label className={styles.label} htmlFor={progressId}>资料整理完成度</label>
          <span className={styles.value} aria-hidden="true">{progress}%</span>
        </div>
        <progress id={progressId} className={styles.progressSemantics} max="100" value={progress}>{progress}%</progress>
        <div className={styles.track} aria-hidden="true">
          <motion.div
            className={styles.fill}
            data-complete={complete}
            initial={false}
            animate={{ scaleX: progress / 100 }}
            transition={{ duration: reduced ? 0 : 0.45, ease: [0.22, 1, 0.36, 1] }}
          />
        </div>
        <p className={styles.status} data-complete={complete} role="status" aria-atomic="true">
          {complete ? <CheckCircle2 size={16} aria-hidden="true" /> : <span className={styles.statusDot} aria-hidden="true" />}
          {progress}% {complete ? '已完成' : '处理中'}
        </p>
      </div>
      <div className={styles.controls}>
        <Button disabled={complete} onClick={advance}>完成下一步</Button>
        <Button variant="secondary" onClick={reset}>重置</Button>
      </div>
    </BusinessDemo>
  );
}

