    <Button variant="secondary" aria-pressed={saved} onClick={()=>setSaved(value=>!value)}><span aria-hidden="true">{saved?'★':'☆'}</span><ScreenReaderText>{saved?'取消收藏资料':'收藏资料'}</ScreenReaderText></Button><p data-ui="aw-business-status" className={cn("aw-business-status")} role="status">{saved?'资料已在当前示例收藏。':'资料尚未收藏。'}</p>
  </BusinessDemo>;
